# Final construction of 9x9 output
base = [[8, 8, 6], [6, 3, 6], [6, 8, 8]]  # corners, center, and rot180
edge = [[6, 8, 8], [6, 3, 6], [8, 8, 6]]   # top/middle/bottom edges

# Construct output grid
output = []
for r in range(3):  # block row
    for c in range(3):  # block col
        if r == 0 and c in (0, 2):
            block = base  # corners in top row
        elif r == 0 and c == 1:
            block = edge  # top-middle
        elif r == 1 and c == 0:
            block = edge  # left-middle
        elif r == 1 and c in (1, 2):
            block = base  # center and right-middle
        elif r == 2 and c in (0, 2):
            block = base  # corners in bottom row
        elif r == 2 and c == 1:
            block = edge  # bottom-middle

        # Add block to output
        for i in range(3):
            row = []
            for j in range(3):
                row.extend(block[i])
            output.append(row)

print("9x9 Output Grid:")
for row in output:
    print(row)
